Here is a complete, lightweight Node.js solution that satisfies all your requirements:

- **Password Hashing:** Uses `bcrypt` to hash the password before saving metadata.
- **Server-Side Validation:** The client submits the password via a POST request; the server verifies the hash using `bcrypt.compare`.
- **Protected Downloads:** Uploads are stored in a private directory (outside the public web root). Express does not serve them statically; files are only streamed to the user via `res.download()` *after* the password matches.

---

### 1. Project Setup

Create a new folder and initialize the project:

```bash
mkdir secure-share
cd secure-share
npm init -y
```

Install the required dependencies:

```bash
npm install express multer bcrypt uuid
```

Your project structure should look like this:

```text
secure-share/
├── node_modules/
├── uploads/         (will be generated automatically)
├── package.json
└── server.js
```

---

### 2. The Code (`server.js`)

Create a file named `server.js` and paste the following:

```javascript
const express = require('express');
const multer = require('multer');
const bcrypt = require('bcrypt');
const { v4: uuidv4 } = require('uuid');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;
const SALT_ROUNDS = 10;

// Ensure uploads folder exists (stored outside public access)
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir);
}

// In-memory store for file metadata. 
// (For persistence across server restarts, you can use SQLite, PostgreSQL, or a JSON file)
const filesDB = new Map();

// Configure Multer storage (renames files to UUID to prevent name collisions/traversal)
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, uploadDir),
  filename: (req, file, cb) => cb(null, `${uuidv4()}-${Date.now()}`)
});
const upload = multer({ 
  storage, 
  limits: { fileSize: 50 * 1024 * 1024 } // 50MB file limit
});

// Middleware to parse form data
app.use(express.urlencoded({ extended: true }));

// --- ROUTES ---

// 1. Home Page: Upload Form
app.get('/', (req, res) => {
  res.send(`
    <!DOCTYPE html>
    <html lang="en">
    <head>
      <meta charset="UTF-8">
      <title>Secure File Share</title>
      <style>
        body { font-family: sans-serif; display: grid; place-content: center; height: 100vh; margin: 0; background: #f4f4f9; }
        form { background: white; padding: 2rem; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); width: 320px; }
        div { margin-bottom: 1rem; }
        label { display: block; margin-bottom: .25rem; font-weight: bold; }
        input[type="text"], input[type="file"] { width: 100%; box-sizing: border-box; }
        button { width: 100%; padding: .5rem; background: #0066cc; color: white; border: none; border-radius: 4px; cursor: pointer; }
      </style>
    </head>
    <body>
      <form action="/upload" method="POST" enctype="multipart/form-data">
        <h2>Share a File</h2>
        <div>
          <label>Choose File:</label>
          <input type="file" name="file" required />
        </div>
        <div>
          <label>Set Password:</label>
          <input type="text" name="password" required />
        </div>
        <button type="submit">Upload & Protect</button>
      </form>
    </body>
    </html>
  `);
});

// 2. Upload Endpoint: Hash password and store file info
app.post('/upload', upload.single('file'), async (req, res) => {
  try {
    if (!req.file || !req.body.password) {
      return res.status(400).send('File and password are required.');
    }

    const fileId = uuidv4();
    // Hash the password securely
    const passwordHash = await bcrypt.hash(req.body.password, SALT_ROUNDS);

    // Save record to DB
    filesDB.set(fileId, {
      id: fileId,
      originalName: req.file.originalname,
      diskPath: req.file.path,
      passwordHash: passwordHash
    });

    const shareUrl = `${req.protocol}://${req.get('host')}/share/${fileId}`;
    res.send(`
      <body style="font-family: sans-serif; text-align: center; margin-top: 50px;">
        <h2>File uploaded successfully!</h2>
        <p>Send this link to your friend:</p>
        <input style="width: 400px; padding: 8px;" readonly value="${shareUrl}" />
        <br><br>
        <a href="/">Upload another file</a>
      </body>
    `);
  } catch (error) {
    console.error(error);
    res.status(500).send('An error occurred during upload.');
  }
});

// 3. Share Page: Prompt recipient for password
app.get('/share/:id', (req, res) => {
  const fileRecord = filesDB.get(req.params.id);

  if (!fileRecord) {
    return res.status(404).send('File not found or expired.');
  }

  res.send(`
    <!DOCTYPE html>
    <html lang="en">
    <head>
      <meta charset="UTF-8">
      <title>Download Protected File</title>
      <style>
        body { font-family: sans-serif; display: grid; place-content: center; height: 100vh; margin: 0; background: #f4f4f9; }
        form { background: white; padding: 2rem; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); width: 320px; }
        div { margin-bottom: 1rem; }
        input[type="password"] { width: 100%; box-sizing: border-box; padding: .5rem; }
        button { width: 100%; padding: .5rem; background: #28a745; color: white; border: none; border-radius: 4px; cursor: pointer; }
      </style>
    </head>
    <body>
      <form action="/download/${req.params.id}" method="POST">
        <h3>Password Required</h3>
        <p>File: <strong>${fileRecord.originalName}</strong></p>
        <div>
          <input type="password" name="password" placeholder="Enter password" required />
        </div>
        <button type="submit">Download</button>
      </form>
    </body>
    </html>
  `);
});

// 4. Download Endpoint: Verify password server-side, then stream file
app.post('/download/:id', async (req, res) => {
  const fileRecord = filesDB.get(req.params.id);

  if (!fileRecord) {
    return res.status(404).send('File not found or expired.');
  }

  const enteredPassword = req.body.password || '';

  // Server-side bcrypt check against the stored hash
  const isMatch = await bcrypt.compare(enteredPassword, fileRecord.passwordHash);

  if (!isMatch) {
    return res.status(401).send(`
      <body style="font-family: sans-serif; text-align: center; margin-top: 50px;">
        <h2 style="color: red;">Incorrect Password</h2>
        <a href="/share/${req.params.id}">Try Again</a>
      </body>
    `);
  }

  // Password verified: initiate protected download
  res.download(fileRecord.diskPath, fileRecord.originalName);
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

---

### 3. How to Run It

1. Start the server:
   ```bash
   node server.js
   ```
2. Open your browser and go to `http://localhost:3000`.
3. Choose a file, enter a password, and click **Upload & Protect**.
4. Copy the generated link (e.g., `http://localhost:3000/share/<uuid>`) and open it in a different browser or an Incognito window.
5. Provide the password to trigger the download.

